css:
/* DMZ Ranked Remote App UI v1
   Streamed by the Android app from this repository.
   Edit this file to update Stable + Beta WebView presentation without rebuilding the APK. */

/* Beta-only Unofficial App section.
   Most of the visual language intentionally comes from dmzranked.com's own
   .wrap, nav.tabs, section, .sect-hero, .card and .section-title rules. */

nav.tabs button.hs-unofficial-tab{
  border-color:rgba(230,169,43,.34);
}
nav.tabs button.hs-unofficial-tab:hover{
  border-color:rgba(226,180,96,.6);
}
nav.tabs button.hs-unofficial-tab.active{
  color:#0a0e10;
  background:linear-gradient(180deg,var(--gold-b),var(--gold-d));
  border-color:var(--gold-d);
  box-shadow:0 0 16px var(--glow);
}

#unofficial-app .hs-app-intro{
  margin:0;
  color:var(--muted);
  font-family:var(--f-ui);
  font-size:14px;
  line-height:1.6;
}
#unofficial-app .hs-app-intro b{
  color:var(--txt);
}
#unofficial-app .hs-app-meta{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:14px;
}
#unofficial-app .hs-app-pill{
  font-family:var(--f-ui);
  font-weight:700;
  font-size:11px;
  letter-spacing:.7px;
  text-transform:uppercase;
  color:var(--muted);
  background:rgba(0,0,0,.34);
  border:1px solid var(--line);
  border-radius:4px;
  padding:5px 10px;
}
#unofficial-app .hs-app-pill.beta,
#unofficial-app .hs-app-pill[data-hs-channel-badge]:not(.stable){
  color:#0a0e10;
  background:linear-gradient(180deg,var(--gold-b),var(--gold-d));
  border-color:var(--gold-d);
}
#unofficial-app .hs-app-pill.stable{
  color:#dff7e5;
  background:rgba(23,75,38,.72);
  border-color:rgba(95,207,122,.48);
}
#unofficial-app .hs-app-row{
  display:grid;
  grid-template-columns:180px minmax(0,1fr);
  gap:14px;
  padding:12px 0;
  border-bottom:1px solid var(--line2);
}
#unofficial-app .hs-app-row:last-child{
  border-bottom:0;
  padding-bottom:0;
}
#unofficial-app .hs-app-label{
  font-family:var(--f-ui);
  font-size:12px;
  font-weight:700;
  letter-spacing:.8px;
  text-transform:uppercase;
  color:var(--muted2);
}
#unofficial-app .hs-app-value{
  min-width:0;
  color:var(--txt);
  font-family:var(--f-ui);
  font-size:14px;
}
#unofficial-app .hs-app-status{
  display:inline-flex;
  align-items:center;
  gap:7px;
}
#unofficial-app .hs-app-dot{
  width:8px;
  height:8px;
  border-radius:50%;
  background:var(--good);
  box-shadow:0 0 8px rgba(95,207,122,.58);
}
#unofficial-app .hs-app-list{
  margin:0;
  padding-left:18px;
  color:var(--muted);
  font-family:var(--f-ui);
  font-size:14px;
  line-height:1.65;
}
#unofficial-app .hs-app-list b{
  color:var(--txt);
}
#unofficial-app .hs-app-notice{
  border-color:rgba(95,207,122,.25);
  border-top-color:rgba(95,207,122,.48);
}
#unofficial-app .hs-app-notice p{
  margin:0;
  color:var(--muted);
  font-family:var(--f-ui);
  font-size:13px;
  line-height:1.55;
}

@media(max-width:640px){
  #unofficial-app .hs-app-row{
    grid-template-columns:1fr;
    gap:4px;
  }
}


/* Mobile-first active operator summary and app-exclusive message system. */
#unofficial-app .hs-active-stats-card,
#unofficial-app .hs-app-messages{
  border-top-color:rgba(230,169,43,.54);
}
#unofficial-app .hs-app-heading-row{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:12px;
  margin-bottom:12px;
}
#unofficial-app .hs-app-heading-row .section-title{
  margin:2px 0 0;
}
#unofficial-app .hs-app-eyebrow{
  color:var(--muted2);
  font-family:var(--f-ui);
  font-size:10px;
  font-weight:800;
  letter-spacing:1px;
  text-transform:uppercase;
}
#unofficial-app .hs-app-heading-actions{
  display:flex;
  align-items:center;
  gap:7px;
  flex-wrap:wrap;
  justify-content:flex-end;
}
#unofficial-app .hs-stat-state,
#unofficial-app .hs-exclusive-badge{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:28px;
  padding:4px 8px;
  border:1px solid var(--line);
  border-radius:5px;
  background:rgba(0,0,0,.32);
  color:var(--muted);
  font-family:var(--f-ui);
  font-size:10px;
  font-weight:900;
  letter-spacing:.7px;
  text-transform:uppercase;
}
#unofficial-app .hs-stat-state.live{
  border-color:rgba(95,207,122,.42);
  color:var(--good);
}
#unofficial-app .hs-stat-state.loading{
  border-color:rgba(230,169,43,.4);
  color:var(--gold-b);
}
#unofficial-app .hs-stat-state.empty,
#unofficial-app .hs-stat-state.error{
  color:var(--muted2);
}
#unofficial-app .hs-exclusive-badge{
  border-color:rgba(230,169,43,.5);
  color:var(--gold-b);
}
#unofficial-app .hs-stat-refresh{
  min-height:34px;
  padding:6px 10px;
  border:1px solid rgba(230,169,43,.4);
  border-radius:6px;
  background:rgba(0,0,0,.3);
  color:var(--txt);
  font-family:var(--f-ui);
  font-size:11px;
  font-weight:800;
}
#unofficial-app .hs-stat-refresh:active{
  transform:translateY(1px);
}
#unofficial-app .hs-stat-grid{
  display:grid;
  grid-template-columns:1.35fr repeat(4,minmax(0,1fr));
  gap:8px;
}
#unofficial-app .hs-stat-tile{
  min-width:0;
  padding:10px;
  border:1px solid var(--line2);
  border-radius:7px;
  background:rgba(0,0,0,.22);
}
#unofficial-app .hs-stat-label{
  display:block;
  margin-bottom:5px;
  color:var(--muted2);
  font-family:var(--f-ui);
  font-size:9px;
  font-weight:800;
  letter-spacing:.8px;
  text-transform:uppercase;
}
#unofficial-app .hs-stat-tile strong{
  display:block;
  overflow:hidden;
  color:var(--txt);
  font-family:var(--f-ui);
  font-size:13px;
  line-height:1.25;
  text-overflow:ellipsis;
  white-space:nowrap;
}
#unofficial-app .hs-stat-footer{
  display:flex;
  align-items:center;
  gap:6px;
  margin-top:10px;
  color:var(--muted2);
  font-family:var(--f-ui);
  font-size:10.5px;
}
#unofficial-app .hs-exclusive-note{
  margin-bottom:10px;
  padding:9px 10px;
  border-left:3px solid var(--gold-d);
  background:rgba(230,169,43,.08);
  color:var(--muted);
  font-family:var(--f-ui);
  font-size:11.5px;
  line-height:1.45;
}
#unofficial-app .hs-exclusive-note b{
  color:var(--gold-b);
}
#unofficial-app .hs-app-message-list{
  display:grid;
  gap:7px;
}
#unofficial-app .hs-app-message-item{
  display:grid;
  grid-template-columns:92px minmax(0,1fr);
  gap:8px;
  align-items:start;
  padding:9px 10px;
  border:1px solid var(--line2);
  border-radius:6px;
  background:rgba(0,0,0,.2);
}
#unofficial-app .hs-app-message-label{
  color:var(--muted2);
  font-family:var(--f-ui);
  font-size:10px;
  font-weight:900;
  letter-spacing:.6px;
  text-transform:uppercase;
}
#unofficial-app .hs-app-message-copy{
  color:var(--txt);
  font-family:var(--f-ui);
  font-size:12px;
  line-height:1.45;
}

@media(max-width:760px){
  #unofficial-app{
    padding-left:6px;
    padding-right:6px;
  }
  #unofficial-app .card{
    margin-left:0;
    margin-right:0;
  }
  #unofficial-app .hs-stat-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:7px;
  }
  #unofficial-app .hs-stat-tile.wide{
    grid-column:1/-1;
  }
  #unofficial-app .hs-stat-tile{
    padding:9px;
  }
  #unofficial-app .hs-app-heading-row{
    align-items:center;
  }
}
@media(max-width:430px){
  #unofficial-app .hs-app-heading-row{
    flex-direction:column;
    align-items:stretch;
    gap:8px;
  }
  #unofficial-app .hs-app-heading-actions{
    justify-content:space-between;
  }
  #unofficial-app .hs-stat-state,
  #unofficial-app .hs-exclusive-badge{
    align-self:flex-start;
  }
  #unofficial-app .hs-stat-refresh{
    min-height:40px;
  }
  #unofficial-app .hs-app-message-item{
    grid-template-columns:1fr;
    gap:3px;
  }
}


/* App-only navigation identity. Only the Unofficial App tab is decorated. */
nav.tabs button.hs-unofficial-tab{
  position:relative;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  flex-wrap:nowrap;
  overflow:visible!important;
  padding-left:12px!important;
  padding-right:44px!important;
}
nav.tabs button.hs-unofficial-tab .hs-unofficial-tab-logo{
  display:block!important;
  width:24px;
  height:24px;
  flex:0 0 24px;
  opacity:1!important;
  visibility:visible!important;
  object-fit:contain;
  filter:drop-shadow(0 0 5px rgba(230,169,43,.28));
}
nav.tabs button.hs-unofficial-tab .hs-unofficial-tab-logo.failed{
  display:none!important;
}
nav.tabs button.hs-unofficial-tab .hs-unofficial-tab-label{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
nav.tabs button.hs-unofficial-tab .hs-unofficial-tab-channel,
#unofficial-app .hs-app-channel-badge,
.dmz-hs-channel-badge{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:18px;
  padding:2px 6px;
  border:1px solid rgba(246,196,83,.52);
  border-radius:5px;
  color:#0a0e10;
  background:linear-gradient(180deg,#f8ca59,#d69a22);
  font-family:var(--f-ui,inherit);
  font-size:8.5px;
  font-weight:900;
  line-height:1;
  letter-spacing:.55px;
  text-transform:uppercase;
  white-space:nowrap;
}
nav.tabs button.hs-unofficial-tab .hs-unofficial-tab-channel.stable,
#unofficial-app .hs-app-channel-badge.stable,
.dmz-hs-channel-badge.stable{
  color:#dff7e5;
  border-color:rgba(95,207,122,.48);
  background:rgba(23,75,38,.72);
}

/* App tab mirrors dmzranked.com's own top-level notification dot state.
   Keep this as the same small red dot language used by Community / Updates. */
nav.tabs button.hs-unofficial-tab .hs-unofficial-tab-notify{
  position:relative!important;
  top:auto!important;
  right:auto!important;
  z-index:auto!important;
  display:inline-block!important;
  box-sizing:border-box;
  width:10px!important;
  min-width:10px!important;
  height:10px!important;
  min-height:10px!important;
  flex:0 0 10px;
  margin:0 0 0 2px!important;
  padding:0!important;
  border:1px solid rgba(255,255,255,.34)!important;
  border-radius:50%!important;
  background:#ef5350!important;
  box-shadow:0 0 7px rgba(239,83,80,.8)!important;
  animation:dotpulse 1.8s ease-in-out infinite;
  pointer-events:none;
}
nav.tabs button.hs-unofficial-tab .hs-unofficial-tab-notify[hidden]{
  display:none!important;
}

/* Upgrade dmzranked.com's existing red notification dots using only an app-side
   CSS override. The website still owns when each indicator is shown/hidden. */
.wrap nav.tabs .tab-dot,
.wrap .subtabs .tab-dot,
.wrap .sub-tabs .tab-dot{
  position:relative!important;
  display:inline-block;
  box-sizing:border-box;
  width:10px!important;
  min-width:10px!important;
  height:10px!important;
  min-height:10px!important;
  margin-left:6px!important;
  padding:0!important;
  border:1px solid rgba(255,255,255,.34)!important;
  border-radius:999px!important;
  background:#e1262c!important;
  box-shadow:0 0 0 2px rgba(7,10,11,.78),0 0 9px rgba(225,38,44,.72)!important;
  vertical-align:middle;
}
.wrap nav.tabs .tab-dot[style*="display:none"],
.wrap nav.tabs .tab-dot[style*="display: none"],
.wrap .subtabs .tab-dot[style*="display:none"],
.wrap .subtabs .tab-dot[style*="display: none"],
.wrap .sub-tabs .tab-dot[style*="display:none"],
.wrap .sub-tabs .tab-dot[style*="display: none"]{
  display:none!important;
}

/* Keep the site's numeric Under Review badge visually consistent. */
.wrap #reviewCount.sub-badge{
  min-width:18px;
  height:18px;
  margin-left:6px;
  padding:0 5px;
  align-items:center;
  justify-content:center;
  border:1px solid rgba(255,255,255,.24);
  border-radius:999px;
  background:linear-gradient(180deg,#ff5f62,#b80f15);
  color:#fff;
  box-shadow:0 0 8px rgba(225,38,44,.5);
  font-size:10px;
  font-weight:900;
  line-height:18px;
}

/* Compact app-only season header.
   The website still renders and updates the original banner/countdown; JS mirrors
   those values here, then hides the two tall source blocks only inside the app. */
#board.hs-compact-season-ready > #seasonBanner,
#board.hs-compact-season-ready > #seasonBar{
  display:none!important;
}

#hs-compact-season-header{
  --hs-season-bg:none;
  position:relative;
  isolation:isolate;
  overflow:hidden;
  box-sizing:border-box;
  width:100%;
  min-height:76px;
  margin:0 0 12px;
  padding:9px 11px;
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  align-items:center;
  gap:9px;
  border:1px solid var(--line,rgba(226,180,96,.18));
  border-left:3px solid var(--gold,#e6a92b);
  border-radius:9px;
  background-image:
    linear-gradient(90deg,rgba(7,10,11,.94) 0%,rgba(7,10,11,.82) 48%,rgba(7,10,11,.68) 100%),
    var(--hs-season-bg);
  background-size:cover;
  background-position:center;
  box-shadow:0 7px 20px rgba(0,0,0,.28);
}
#hs-compact-season-header::after{
  content:"";
  position:absolute;
  inset:0;
  z-index:-1;
  pointer-events:none;
  background:linear-gradient(90deg,rgba(230,169,43,.08),transparent 58%);
}
#hs-compact-season-header .hs-compact-season-copy{
  min-width:0;
}
#hs-compact-season-header .hs-compact-season-kicker{
  overflow:hidden;
  margin:0 0 2px;
  color:var(--gold-b,#f5c451);
  font-family:var(--f-ui,'Rajdhani',system-ui,sans-serif);
  font-size:8.5px;
  font-weight:800;
  line-height:1.1;
  letter-spacing:1.6px;
  text-overflow:ellipsis;
  text-transform:uppercase;
  white-space:nowrap;
}
#hs-compact-season-header .hs-compact-season-name{
  overflow:hidden;
  color:#fff;
  font-family:var(--f-display,'Oswald','Arial Narrow',system-ui,sans-serif);
  font-size:18px;
  font-weight:800;
  line-height:1.05;
  letter-spacing:.8px;
  text-overflow:ellipsis;
  text-transform:uppercase;
  white-space:nowrap;
  text-shadow:0 1px 4px rgba(0,0,0,.7);
}
#hs-compact-season-header .hs-compact-season-range{
  overflow:hidden;
  margin-top:3px;
  color:var(--muted,#9aa39b);
  font-family:var(--f-ui,'Rajdhani',system-ui,sans-serif);
  font-size:10.5px;
  font-weight:650;
  line-height:1.15;
  text-overflow:ellipsis;
  white-space:nowrap;
}
#hs-compact-season-header .hs-compact-season-count{
  min-width:0;
  text-align:right;
}
#hs-compact-season-header .cd-lab{
  margin:0 0 3px;
  color:var(--muted2,#727b73);
  font-size:7px;
  font-weight:800;
  letter-spacing:1.1px;
  line-height:1;
}
#hs-compact-season-header .cd-row{
  display:flex;
  justify-content:flex-end;
  gap:3px;
}
#hs-compact-season-header .cd-seg{
  min-width:31px;
  padding:4px 4px 3px;
  border:1px solid rgba(226,180,96,.18);
  border-radius:5px;
  background:rgba(0,0,0,.38);
  box-shadow:none;
}
#hs-compact-season-header .cd-seg b{
  color:var(--gold-b,#f5c451);
  font-size:15px;
  line-height:1;
  letter-spacing:0;
}
#hs-compact-season-header .cd-seg i{
  margin-top:2px;
  color:var(--muted2,#727b73);
  font-size:6.5px;
  line-height:1;
  letter-spacing:.7px;
}
#hs-compact-season-header .hs-compact-season-status{
  padding:5px 8px;
  border:1px solid rgba(230,169,43,.28);
  border-radius:5px;
  background:rgba(0,0,0,.32);
  color:var(--gold-b,#f5c451);
  font-family:var(--f-ui,'Rajdhani',system-ui,sans-serif);
  font-size:9px;
  font-weight:800;
  letter-spacing:.5px;
  text-transform:uppercase;
  white-space:nowrap;
}

@media(max-width:520px){
  #hs-compact-season-header{
    min-height:70px;
    gap:6px;
    margin-bottom:9px;
    padding:8px 8px;
  }
  #hs-compact-season-header .hs-compact-season-kicker{font-size:7.5px;letter-spacing:1.15px}
  #hs-compact-season-header .hs-compact-season-name{font-size:16px}
  #hs-compact-season-header .hs-compact-season-range{font-size:9.5px}
  #hs-compact-season-header .cd-row{gap:2px}
  #hs-compact-season-header .cd-seg{min-width:28px;padding:3px 3px 2px}
  #hs-compact-season-header .cd-seg b{font-size:13px}
  #hs-compact-season-header .cd-seg i{font-size:6px;letter-spacing:.45px}
  #hs-compact-season-header .cd-lab{font-size:6.5px;letter-spacing:.8px}
}

@media(max-width:370px){
  #hs-compact-season-header{grid-template-columns:minmax(0,1fr) 120px}
  #hs-compact-season-header .cd-seg{min-width:26px;padding-inline:2px}
  #hs-compact-season-header .hs-compact-season-name{font-size:15px}
  #hs-compact-season-header .hs-compact-season-range{font-size:9px}
}

/* Active user standings lives directly below the Harley's Studios app message.
   Keep the existing app JS/data, but present the row using dmzranked.com's
   leaderboard visual language instead of a separate dashboard/tile layout. */
#dmz-hs-active-user-stats{
  box-sizing:border-box;
  width:calc(100% - 32px);
  max-width:940px;
  margin:14px auto 16px;
  position:relative;
  z-index:1;
  color:var(--txt,#e9ede9);
  font-family:var(--f-body,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif);
}
#dmz-hs-active-user-stats .hs-global-stats-card{
  position:relative;
  overflow:hidden;
  box-sizing:border-box;
  padding:14px 16px 12px;
  background:var(--panel,rgba(17,23,25,.86));
  backdrop-filter:blur(7px);
  border:1px solid var(--line,rgba(226,180,96,.16));
  border-top:2px solid rgba(230,169,43,.4);
  border-radius:9px;
  box-shadow:0 10px 30px rgba(0,0,0,.5);
}
#dmz-hs-active-user-stats .hs-global-stats-heading{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  margin-bottom:10px;
}
#dmz-hs-active-user-stats .hs-global-stats-heading>div:first-child{min-width:0}
#dmz-hs-active-user-stats .hs-app-eyebrow{
  margin-bottom:2px;
  color:var(--muted2,#727b73);
  font-family:var(--f-ui,'Rajdhani',system-ui,sans-serif);
  font-size:9px;
  font-weight:800;
  letter-spacing:1.1px;
  text-transform:uppercase;
}
#dmz-hs-active-user-stats .hs-global-stats-title{
  position:relative;
  margin:0;
  padding-left:11px;
  color:var(--gold-b,#f5c451);
  font-family:var(--f-display,'Oswald','Arial Narrow',system-ui,sans-serif);
  font-size:16px;
  font-weight:700;
  line-height:1.2;
  letter-spacing:1.1px;
  text-transform:uppercase;
}
#dmz-hs-active-user-stats .hs-global-stats-title::before{
  content:"";
  position:absolute;
  left:0;
  top:2px;
  bottom:2px;
  width:4px;
  border-radius:1px;
  background:var(--gold,#e6a92b);
  box-shadow:0 0 8px var(--glow,rgba(230,169,43,.28));
}
#dmz-hs-active-user-stats .hs-app-heading-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:6px;
  flex-wrap:wrap;
}
#dmz-hs-active-user-stats .hs-app-channel-badge,
#dmz-hs-active-user-stats .hs-stat-state{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:25px;
  padding:4px 8px;
  border-radius:5px;
  font-family:var(--f-ui,'Rajdhani',system-ui,sans-serif);
  font-size:9px;
  font-weight:900;
  line-height:1;
