/* DMZ Ranked app-only mobile QoL layer.
   Injected into dmzranked.com by the Android beta package only. */
html{scroll-behavior:smooth}
button,[role="button"],select,input[type="button"],input[type="submit"]{touch-action:manipulation}
input,select,textarea{font-size:max(16px,1em)}
.tabs{
  -webkit-overflow-scrolling:touch;
  overscroll-behavior-x:contain;
}
#hs-app-back-top{
  position:fixed;
  right:14px;
  bottom:18px;
  z-index:80;
  width:44px;
  height:44px;
  border:1px solid rgba(246,196,83,.62);
  border-radius:12px;
  background:rgba(10,13,11,.94);
  color:#f6c453;
  box-shadow:0 6px 20px rgba(0,0,0,.32);
  font:700 20px/1 sans-serif;
  display:none;
  align-items:center;
  justify-content:center;
}
#hs-app-back-top.hs-show{display:flex}
@media (max-width:900px){
  .wrap nav.tabs{
    display:grid!important;
    grid-template-columns:repeat(3,minmax(0,1fr))!important;
    gap:6px!important;
    align-items:stretch!important;
    justify-content:stretch!important;
    overflow:visible!important;
    padding:6px!important;
    scroll-snap-type:none!important;
  }
  .wrap nav.tabs>button,
  .wrap nav.tabs>[role="button"],
  .wrap nav.tabs>a{
    width:100%!important;
    min-width:0!important;
    min-height:44px!important;
    margin:0!important;
    padding:7px 5px!important;
    display:flex!important;
    align-items:center!important;
    justify-content:center!important;
    text-align:center!important;
    white-space:normal!important;
    overflow-wrap:anywhere!important;
    line-height:1.15!important;
    touch-action:manipulation;
  }
  .wrap nav.tabs>button.hs-unofficial-tab{
    grid-column:1/-1!important;
    min-height:48px!important;
  }
}
@media (max-width:640px){
  nav.tabs button.hs-unofficial-tab .hs-unofficial-tab-logo{width:20px;height:20px;flex-basis:20px}
  nav.tabs button.hs-unofficial-tab .hs-unofficial-tab-notify{top:6px;right:7px}
}
