    padding:5px!important;
  }
  .wrap nav.tabs>button,
  .wrap nav.tabs>[role="button"],
  .wrap nav.tabs>a{
    min-height:46px!important;
    font-size:11px!important;
    letter-spacing:.2px!important;
  }
