/* DMZ Ranked Log a Raid SR Summary Fix v4
   Scoped only to Log a Raid's live SR preview.
   app.js wraps the SR text node so the number and rank badge can be laid out
   independently instead of competing inside the same <b>. */
@media (max-width:700px){
  #log #preview{
    box-sizing:border-box!important;
    padding:14px 16px!important;
    overflow:hidden!important;
  }

  #log #preview .rowline{
    box-sizing:border-box!important;
    display:grid!important;
    grid-template-columns:minmax(0,1fr) auto!important;
    align-items:center!important;
    gap:8px 14px!important;
    width:100%!important;
    min-width:0!important;
    padding:8px 0!important;
  }

  #log #preview .rowline > span:first-child{
    min-width:0!important;
    max-width:100%!important;
    overflow-wrap:anywhere!important;
    text-align:left!important;
  }

  #log #preview .rowline > b{
    min-width:0!important;
    max-width:100%!important;
    margin:0!important;
    justify-self:end!important;
    text-align:right!important;
    white-space:nowrap!important;
  }

  #log #preview #pv-cur,
  #log #preview #pv-new{
    display:flex!important;
    align-items:center!important;
    justify-content:flex-end!important;
    gap:10px!important;
    min-width:0!important;
    max-width:100%!important;
    white-space:nowrap!important;
    line-height:1!important;
  }

  #log #preview .hs-app-sr-number{
    display:inline-block!important;
    flex:0 0 auto!important;
    min-width:max-content!important;
    white-space:nowrap!important;
    line-height:1!important;
  }

  #log #preview #pv-cur .badge,
  #log #preview #pv-new .badge{
    position:relative!important;
    flex:0 0 auto!important;
    max-width:100%!important;
    margin:0!important;
    transform:none!important;
    vertical-align:middle!important;
  }

  #log #preview hr{
    margin:10px 0!important;
  }

  #log #preview #pv-net{
    line-height:1!important;
  }
}

/* On phone widths, give Current/New rank their own second line.
   This completely removes the possibility of the SR text colliding with the
   rank chip while leaving the other preview rows as compact two-column rows. */
@media (max-width:480px){
  #log #preview .rowline.hs-app-rank-preview-row{
    grid-template-columns:1fr!important;
    gap:7px!important;
    padding-top:9px!important;
    padding-bottom:9px!important;
  }

  #log #preview .rowline.hs-app-rank-preview-row > span:first-child{
    grid-column:1!important;
    grid-row:1!important;
  }

  #log #preview .rowline.hs-app-rank-preview-row > b{
    grid-column:1!important;
    grid-row:2!important;
    justify-self:end!important;
