      if (host.previousElementSibling !== message) message.insertAdjacentElement("afterend", host);
    } else if (!host.parentNode) {
      const nav = findSiteNav();
      if (nav && nav.parentNode) nav.parentNode.insertBefore(host, nav);
    }

    return host;
